import json
from pathlib import Path
from langflow.custom import CustomComponent

class DataFetcher(CustomComponent):
    display_name = 'Data Fetcher'
    description = 'Ambil data settlement dari mock data'

    def build_config(self):
        return {
            'store_id': {'display_name': 'Store ID', 'required': True},
            'scenario': {'display_name': 'Scenario', 'value': 'S1_AMAN', 'required': False},
        }

    def build(self, store_id: str, scenario: str = 'S1_AMAN') -> dict:
        mock_data_path = Path('/app/langflow/custom_components/mock_data/store_scenarios.json')
        with open(mock_data_path, 'r', encoding='utf-8') as f:
            all_scenarios = json.load(f)
        if scenario not in all_scenarios['scenarios']:
            raise ValueError(f'Scenario {scenario} tidak ditemukan')
        data = all_scenarios['scenarios'][scenario]['data'].copy()
        data['store_id'] = store_id
        return data
